407:   function handleEvents(events) {
408:     if (!events?.length) return;
409:     for (const ev of events) {
410:       if (!ev) continue;
411:       switch (ev.type) {
412:         case 'hit':
413:         case 'critical':
414:           view.handleEvent(ev);
415:           if (ev.defender === localSlot && controlSettings.haptic && navigator.vibrate) {
416:             navigator.vibrate(ev.type === 'critical' ? 45 : 18);
417:           }
418:           break;
419:         case 'block':
420:         case 'guardBreak':
421:         case 'dodge':
422:         case 'dodgeSuccess':
423:         case 'whiff':
424:           view.handleEvent(ev);
425:           break;
426:         case 'getUp':
427:           view.handleEvent(ev);
428:           announce('LEVANTOU!', 'A luta continua', 1100);
429:           break;
430:         case 'knockdown': {
431:           view.handleEvent(ev);
432:           const f = engine.fighters.find((x) => x.id === ev.id);
433:           announce('KNOCKDOWN!', f ? f.name : '', 1600);
434:           break;
435:         }
436:         case 'count':
437:           showCount(ev.count);
438:           break;
439:         case 'ko':
440:           view.handleEvent(ev);
441:           announce('NOCAUTE!', 'A luta acabou', 2200);
442:           break;
443:         case 'roundStart':
444:           announce(`ROUND ${ev.round}`, eventName, 1300);
445:           break;
446:         case 'roundEnd':
447:           announce('FIM DO ROUND', 'Os juízes registram o round', 1500);
448:           break;
449:         case 'decision':
450:           announce('DECISÃO', 'Os juízes vão anunciar', 1600);
451:           break;
452:         case 'result':
453:           // The authoritative result is processed from engine.result / the snapshot.
454:           break;
455:         default:
456:           view.handleEvent(ev);
457:           break;
458:       }
459:     }
460:     ui.app.audio.handleEvents(events);
461:     ui.app.audio.setHeat(view.heat);
462:   }
