464:   // -------------------------------------------------------------------------
465:   // Result, career consequences, wager settlement
466:   // -------------------------------------------------------------------------
467:   function settleMultiplayer(result) {
468:     if (mode !== 'multiplayer' || !match) return null;
469:     const wager = Math.max(0, Math.min(500, Number(match.wager) || 0));
470:     const localWon = result.winnerId === localSlot;
471:     const localLost = !!result.winnerId && !localWon;
472:     const receipt = matchReceipt({
473:       matchId: match.matchId,
474:       p1: match.p1?.name,
475:       p2: match.p2?.name,
476:       wager,
477:       result,
478:     });
479:     const fallback = { wager, delta: 0, localWon, localLost, receipt, balance: save?.career?.coins ?? null };
480:     if (!save?.career) return fallback;
481: 
482:     save.multiplayer = save.multiplayer || { history: [], lastCode: null, name: save.profile?.name, totalMatches: 0, wins: 0 };
483:     save.multiplayer.history = Array.isArray(save.multiplayer.history) ? save.multiplayer.history : [];
484:     const previous = save.multiplayer.history.find((entry) => entry.matchId === match.matchId);
485:     if (previous) {
486:       return {
487:         wager: previous.wager,
488:         delta: previous.coinsDelta,
489:         localWon: previous.won,
490:         localLost: previous.lost,
491:         receipt: previous.receipt,
492:         balance: save.career.coins,
493:         replay: true,
494:       };
495:     }
496: 
497:     let delta = 0;
498:     if (localWon) delta = wager;
499:     else if (localLost) delta = -Math.min(wager, Math.max(0, save.career.coins));
500:     if (delta) addCoins(save, delta, 'Aposta online virtual');
501: 
502:     save.multiplayer.totalMatches = (save.multiplayer.totalMatches || 0) + 1;
503:     if (localWon) save.multiplayer.wins = (save.multiplayer.wins || 0) + 1;
504:     save.multiplayer.lastCode = match.code || null;
505:     save.multiplayer.history.unshift({
506:       matchId: match.matchId,
507:       code: match.code || null,
508:       at: new Date().toISOString(),
509:       opponent: (localSlot === 'p1' ? match.p2?.name : match.p1?.name) || 'Adversário',
510:       result: result.winnerId ? (localWon ? 'V' : 'D') : 'E',
511:       method: result.method,
512:       round: result.round || null,
513:       wager,
514:       coinsDelta: delta,
515:       won: localWon,
516:       lost: localLost,
517:       receipt,
518:     });
519:     if (save.multiplayer.history.length > 30) save.multiplayer.history.length = 30;
520:     persist(save, true);
521:     return { wager, delta, localWon, localLost, receipt, balance: save.career.coins };
522:   }
