524:   function processResult(result) {
525:     if (processed || !result) return;
526:     processed = true;
527:     if (mode === 'career' && save) {
528:       try {
529:         outcome = applyFightResult({
530:           save,
531:           universe: ui.universe,
532:           result,
533:           offer,
534:           division,
535:           arenaId,
536:         });
537:       } catch (err) {
538:         console.error('Falha ao aplicar resultado da carreira', err);
539:         outcome = { ok: false, message: err?.message || 'Falha ao registrar o resultado.' };
540:       }
541:       if (outcome?.ok) persist(save, true);
542:     } else {
543:       multiplayerOutcome = settleMultiplayer(result);
544:       if (multiplayerOutcome) persist(save, true);
545:     }
546: 
547:     if (mode === 'career' && title && outcome?.titleWon) {
548:       view.showBelt({
549:         org: title.org,
550:         tier: outcome.titleWon.tier || title.tier,
551:         name: title.name,
