559:   function scheduleResult(result) {
560:     if (resultShown || resultTimer) return;
561:     const method = result?.method;
562:     const delay = method === 'KO' || method === 'TKO' ? 2350 : method === 'DEC' ? 1050 : 350;
563:     resultTimer = setTimeout(() => {
564:       resultTimer = null;
565:       showResult(result);
566:     }, delay);
567:   }
