569:   function showResult(result) {
570:     if (resultShown || !result) return;
571:     resultShown = true;
572:     paused = true;
573:     closePauseOverlay();
574:     introOverlay.classList.add('hidden');
575:     resultCard.innerHTML = resultMarkup(result);
576:     resultOverlay.classList.remove('hidden');
577:     bindResultActions();
578:     if (mode === 'career') {
579:       if (result.winnerId === 'p1') ui.app.audio.cheer();
580:       else if (!result.winnerId) ui.app.audio.ui();
581:     } else {
582:       if (multiplayerOutcome?.localWon) ui.app.audio.cheer();
583:       else ui.app.audio.ui();
584:     }
585:   }
