587:   function resultMarkup(result) {
588:     const localWon = result.winnerId ? result.winnerId === localSlot : null;
589:     const method = METHOD_LABEL[result.method] || result.method || 'RESULTADO';
590:     const s1 = result.stats?.p1 || {};
591:     const s2 = result.stats?.p2 || {};
592:     const winner = result.winnerName || (result.winnerId === 'p1' ? p1def.name : result.winnerId === 'p2' ? p2def.name : '');
593:     const cards = (result.scorecards || []).map((card) => {
594:       const totalA = card.p1 ?? card.a ?? 0;
595:       const totalB = card.p2 ?? card.b ?? 0;
