951:   function setupTouchControls() {
952:     const touch = el.querySelector('[data-touch-controls]');
953:     const joystick = el.querySelector('[data-joystick]');
954:     const knob = el.querySelector('[data-joystick-knob]');
955:     const actionPad = el.querySelector('[data-action-pad]');
956:     if (!touch || !joystick) return;
957: 
958:     const touchCapable = ui.app.mobile || (typeof matchMedia !== 'undefined' && matchMedia('(pointer:coarse)').matches);
959:     if (!touchCapable) return;
960:     touch.classList.add('enabled');
961: 
962:     const stickSize = Math.max(80, Math.min(190, Number(controlSettings.joystick) || 128));
963:     joystick.style.width = `${stickSize}px`;
964:     joystick.style.height = `${stickSize}px`;
965:     touch.style.setProperty('--ctrl-opacity', String(Math.max(0.3, Math.min(1, Number(controlSettings.opacity) || 0.8))));
966:     const btnScale = Math.max(0.75, Math.min(1.35, (Number(controlSettings.buttons) || 132) / 132));
967:     if (actionPad) actionPad.style.setProperty('--btn-scale', btnScale.toFixed(2));
968:     const side = controlSettings.side === 'left' ? 'left' : 'right';
969:     touch.dataset.side = side;
970: 
971:     const updateStick = (e) => {
972:       const rect = joystick.getBoundingClientRect();
973:       const cx = rect.left + rect.width / 2;
974:       const cy = rect.top + rect.height / 2;
975:       let dx = e.clientX - cx;
976:       let dy = e.clientY - cy;
977:       const radius = rect.width * 0.38;
978:       const length = Math.hypot(dx, dy);
979:       if (length > radius) {
980:         dx = (dx / length) * radius;
981:         dy = (dy / length) * radius;
982:       }
983:       knob.style.transform = `translate(calc(-50% + ${dx}px), calc(-50% + ${dy}px))`;
984:       touchMove.x = dx / radius;
985:       touchMove.y = -dy / radius;
986:     };
987: 
988:     const resetStick = () => {
989:       stickPointer = null;
990:       touchMove.x = 0;
991:       touchMove.y = 0;
992:       knob.style.transform = 'translate(-50%, -50%)';
993:     };
994: 
995:     joystick.addEventListener('pointerdown', (e) => {
996:       e.preventDefault();
997:       stickPointer = e.pointerId;
998:       joystick.setPointerCapture?.(e.pointerId);
999:       updateStick(e);
1000:     });
1001:     joystick.addEventListener('pointermove', (e) => {
1002:       if (stickPointer !== e.pointerId) return;
1003:       e.preventDefault();
1004:       updateStick(e);
1005:     });
1006:     joystick.addEventListener('pointerup', (e) => {
1007:       if (stickPointer === e.pointerId) resetStick();
1008:     });
1009:     joystick.addEventListener('pointercancel', resetStick);
1010: 
1011:     touch.querySelectorAll('[data-touch]').forEach((btn) => {
1012:       const action = btn.dataset.touch;
1013:       btn.addEventListener('pointerdown', (e) => {
1014:         e.preventDefault();
1015:         e.stopPropagation();
1016:         if (action === 'block') {
1017:           blockTouch = true;
1018:           btn.classList.add('pressed');
1019:         } else if (action === 'dodge') {
1020:           queueDodge();
1021:           btn.classList.add('pressed');
1022:         } else {
1023:           queuePunch(action);
1024:           btn.classList.add('pressed');
1025:         }
1026:       });
1027:       const release = () => {
1028:         btn.classList.remove('pressed');
1029:         if (action === 'block') blockTouch = false;
1030:       };
1031:       btn.addEventListener('pointerup', release);
1032:       btn.addEventListener('pointercancel', release);
1033:       btn.addEventListener('pointerleave', release);
1034:     });
1035:   }
1036: 
