1088:   const netHandler = (type, d = {}) => {
1089:     if (mode !== 'multiplayer') return;
1090:     switch (type) {
1091:       case 'state': {
1092:         if (role !== 'guest') break;
1093:         if (Array.isArray(d.events) && d.events.length) handleEvents(d.events);
1094:         if (d.snapshot) {
1095:           remoteStarted();
1096:           engine.applySnapshot(d.snapshot);
1097:           hideReconnect();
1098:           netPaused = false;
1099:           if (d.snapshot.result) processResult(d.snapshot.result);
1100:         }
1101:         break;
1102:       }
1103:       case 'input': {
1104:         if (role !== 'host') break;
1105:         guestInput = sanitizeInput(d.input);
1106:         lastGuestInputAt = performance.now();
1107:         break;
1108:       }
1109:       case 'begin': {
1110:         if (role !== 'guest') break;
1111:         remoteBegin();
1112:         break;
1113:       }
1114:       case 'started': {
1115:         if (role !== 'guest') break;
1116:         remoteStarted();
1117:         break;
1118:       }
1119:       case 'resync': {
1120:         if (role !== 'host') break;
1121:         sendStateNow();
1122:         break;
1123:       }
1124:       case 'hello': {
1125:         if (role !== 'host') break;
1126:         netPaused = false;
1127:         hideReconnect();
1128:         if (engine.started) sendStateNow();
1129:         break;
1130:       }
