330:       defender.counterWindow = Math.max(defender.counterWindow, 0.65);
331:       attacker.stun = Math.max(attacker.stun, 0.22);
332:       attacker.combo = 0;
333:       this.emit('dodgeSuccess', { id: defender.id, attacker: attacker.id, type: act.type });
