336:     const precision = attr(attacker.attributes, 'precision', 55);
337:     const reflexes = attr(defender.attributes, 'reflexes', 55);
338:     const staminaPenalty = attacker.stamina < 20 ? 0.18 : 0;
339:     let hitChance = 0.70 + def.accuracy + (precision - reflexes) / 240 - staminaPenalty + (act.counter ? 0.16 : 0) + (defender.stun > 0 ? 0.2 : 0);
340:     if (defender.blocking) hitChance += 0.16;
341:     if (Math.random() > clamp(hitChance, 0.28, 0.97)) {
342:       attacker.combo = 0;
343:       this.emit('whiff', { id: attacker.id, type: act.type });
344:       return;
345:     }
346:     const strength = attr(attacker.attributes, 'strength', 55);
347:     const staminaFactor = clamp(0.55 + attacker.stamina / 110, 0.55, 1.15);
348:     let damage = def.damage * (0.72 + strength / 100 * 0.65) * staminaFactor * (0.9 + Math.random() * 0.2);
349:     damage *= style.power || 1;
350:     if (act.counter) damage *= 1.28;
351:     if (attacker.combo > 0) damage *= 1 + Math.min(0.24, attacker.combo * 0.035);
352:     if (defender.stun > 0) damage *= 1.2;
353:     const defense = attr(defender.attributes, 'defense', 55);
354:     damage *= 1 - clamp(defense / 100 * 0.34, 0, 0.38);
355: 
356:     const crit = Math.random() < 0.055 + precision / 1400;
357:     if (crit) damage *= 1.35;
358: 
359:     const target = Math.random() < 0.68 ? 'head' : 'body';
360:     defender.hurtFlash = 0.25;
361:     defender.combo = 0;
362:     attacker.lastHitAt = this.phaseTime;
363: 
364:     if (defender.blocking) {
365:       defender.stats.blocks++;
366:       const guardDmg = def.guardBreak * (0.72 + strength / 160);
367:       defender.guard = Math.max(0, defender.guard - guardDmg);
368:       const chip = damage * 0.17;
369:       defender.hp = Math.max(0, defender.hp - chip);
370:       defender.hurtFlash = 0.12;
371:       this.emit('block', { attacker: attacker.id, defender: defender.id, type: act.type, guard: defender.guard, damage: chip });
