497:       if (winner === -1) scoreA = 9;
498:       if (winner !== 0 && Math.random() < 0.04) { scoreA = 10; scoreB = 10; winner = 0; }
499:       const knocked = winner === 1 ? (b.knockdowns > 0) : (a.knockdowns > 0);
500:       if (knocked && winner !== 0) scoreB = winner === 1 ? 8 : scoreB;
501:       if (knocked && winner === -1) scoreA = 8;
502:       j.scores[0] += scoreA;
503:       j.scores[1] += scoreB;
