689:         Object.assign(f, {
690:           hp: sf.hp, maxHp: sf.maxHp, stamina: sf.stamina, guard: sf.guard, blocking: sf.blocking,
691:           stun: sf.stun, knockdowns: sf.knockdowns, combo: sf.combo, expression: sf.expression,
692:           victory: sf.victory, defeated: sf.defeated, hurtFlash: sf.hurtFlash, facing: sf.facing,
