703:       this.down = { fighter, time: s.down.time, count: s.down.count, fallProgress: s.down.fallProgress, resolved: true, recovered: false };
704:     } else {
705:       this.down = null;
706:     }
707:     if (s.judges) s.judges.forEach((j, i) => { if (this.judges[i]) this.judges[i].scores = [...j.scores]; });
708:     if (s.stats) s.stats.forEach((st, i) => { if (this.fighters[i]) this.fighters[i].stats = { ...st }; });
709:     if (s.phase === 'end') this.finished = true;
710:   }
