716: export class BoxingAI {
717:   constructor(engine, slot, difficulty = 'pro') {
718:     this.engine = engine;
719:     this.slot = slot;
720:     this.id = slot === 0 ? 'p1' : 'p2';
721:     this.me = () => engine.fighters[slot];
722:     this.opp = () => engine.fighters[1 - slot];
723:     const table = { rookie: 0.55, pro: 0.75, elite: 0.9, legend: 1.0 };
724:     this.skill = table[difficulty] ?? 0.78;
725:     this.input = { moveX: 0, moveZ: 0, block: false, dodge: false, punch: null, getUp: false };
726:     this.timer = 0.5 + Math.random() * 0.5;
