729:     this.dodgeTimer = 0;
730:     this.style = this.me().style;
731:     this.aggression = { aggressive: 0.92, defensive: 0.42, technical: 0.6, counter: 0.5, speed: 0.68, pressure: 0.95 }[this.style] ?? 0.65;
732:     this.personality = Math.random();
