735:   think(dt) {
736:     const me = this.me();
737:     const opp = this.opp();
738:     const input = this.input;
739:     input.punch = null;
740:     input.dodge = false;
741:     input.getUp = false;
742:     if (this.engine.phase === 'knockdown' && this.engine.down?.fighter === me) {
743:       input.getUp = Math.random() < this.skill * 0.7;
744:       return null;
745:     }
746:     if (this.engine.phase !== 'fight') return null;
747:     this.timer -= dt;
748:     this.blockTimer = Math.max(0, this.blockTimer - dt);
749:     this.dodgeTimer = Math.max(0, this.dodgeTimer - dt);
750:     const dist = me.distance || Math.hypot(opp.pos.x - me.pos.x, opp.pos.z - me.pos.z);
751:     const oppAttacking = !!opp.action;
752:     const myStamina = me.stamina;
753:     const oppHp = opp.hp / opp.maxHp;
754:     const myHp = me.hp / me.maxHp;
755: 
756:     // Reactive defence (reaction speed increases with difficulty/reflexes).
757:     const reaction = this.skill * (0.5 + (me.attributes.reflexes || 50) / 180);
758:     if (oppAttacking && Math.random() < reaction * 0.5 * dt * 18 && this.dodgeTimer <= 0) {
759:       const styleDodge = this.style === 'counter' || this.style === 'defensive' || this.style === 'speed';
760:       if (Math.random() < (styleDodge ? 0.55 : 0.3) && me.dodge.cooldown <= 0 && myStamina > 18) {
761:         input.dodge = true;
762:         this.dodgeTimer = 0.5;
763:         input.moveX = Math.random() < 0.5 ? -1 : 1;
764:         return null;
765:       }
766:       if (Math.random() < (styleDodge ? 0.5 : 0.66) && myStamina > 10) {
767:         this.blockTimer = 0.22 + Math.random() * 0.3;
768:       }
769:     }
770:     input.block = this.blockTimer > 0 && myStamina > 4;
771:     input.moveX = 0;
772:     input.moveZ = 0;
773: 
774:     if (myStamina < 16 && !input.block) {
775:       // Rest: circle away and guard.
776:       input.moveZ = -0.55;
777:       input.moveX = Math.sin(this.engine.phaseTime * 0.7) * 0.7;
778:       if (dist < 1.6) input.block = Math.random() < 0.5;
779:       if (dist > 2.3) input.moveZ = 0;
780:       return input;
781:     }
782: 
