839: export function simulateQuickFight(p1, p2, { rounds = 3, seed = Date.now() } = {}) {
840:   // Used by "simular luta" and quick background fights. Deterministic-ish, no rendering.
841:   let hp1 = 100, hp2 = 100, st1 = 100, st2 = 100;
842:   let dmg1 = 0, dmg2 = 0;
843:   let kd1 = 0, kd2 = 0;
844:   let round = 1;
845:   let winner = null;
846:   let method = null;
847:   const rating1 = (p1.overall || 60) + (p1.style === 'aggressive' ? 1 : 0);
848:   const rating2 = (p2.overall || 60);
849:   const rnd = mulberry32Local(seed);
850:   for (round = 1; round <= rounds; round++) {
851:     let r = 0;
852:     while (r < 16) {
853:       r++;
854:       const aHits = rnd() < 0.52 + (rating1 - rating2) / 300;
855:       if (aHits) {
856:         const dmg = (3 + rnd() * 10) * (rating1 / rating2);
857:         hp2 -= dmg;
858:         dmg1 += dmg;
859:         st1 -= 3;
860:       } else {
861:         const dmg = (3 + rnd() * 10) * (rating2 / rating1);
862:         hp1 -= dmg;
863:         dmg2 += dmg;
864:         st2 -= 3;
865:       }
866:       if (hp2 <= 0) { hp2 = 0; winner = 'p1'; method = 'KO'; break; }
867:       if (hp1 <= 0) { hp1 = 0; winner = 'p2'; method = 'KO'; break; }
868:     }
869:     if (winner) break;
870:     // between-rounds recovery
871:     hp1 = Math.min(100, hp1 + 6 + (p1.attributes?.recovery || 50) * 0.05);
872:     hp2 = Math.min(100, hp2 + 6 + (p2.attributes?.recovery || 50) * 0.05);
873:     st1 = Math.min(100, st1 + 20);
874:     st2 = Math.min(100, st2 + 20);
875:   }
876:   if (!winner) {
877:     const score1 = dmg1 + (100 - hp1) * 0.3 + (rating1 - 60);
878:     const score2 = dmg2 + (100 - hp2) * 0.3 + (rating2 - 60);
879:     if (Math.abs(score1 - score2) < 4) { method = 'DRAW'; winner = null; }
880:     else { winner = score1 > score2 ? 'p1' : 'p2'; method = 'DEC'; round = rounds; }
881:   }
882:   return { winner, method, round, hp1, hp2, dmg1, dmg2, score1: dmg1, score2: dmg2 };
883: }
884: 
885: function mulberry32Local(seed) {
886:   let a = seed >>> 0;
887:   return function () {
888:     a |= 0; a = (a + 0x6d2b79f5) | 0;
889:     let t = Math.imul(a ^ (a >>> 15), 1 | a);
890:     t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
891:     return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
892:   };
893: }

