885: function mulberry32Local(seed) {
886:   let a = seed >>> 0;
887:   return function () {
888:     a |= 0; a = (a + 0x6d2b79f5) | 0;
889:     let t = Math.imul(a ^ (a >>> 15), 1 | a);
890:     t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
891:     return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
892:   };
893: }

