await page.screenshot({path:'/tmp/opencode/tg-boxing-latest.jpg',type:'jpeg',quality:82,fullPage:false});
console.log('fight bounding box',rect,'screenshot /tmp/opencode/tg-boxing-latest.jpg');
console.log('errors',JSON.stringify(errors.slice(0,20)));
